"""Содержание главы 3 и приложений курсовой работы."""
import ast
import re
from pathlib import Path

from ooxml import chapter, dash_item, figure, heading1, listing, page_break, para, section, table

ROOT = Path(__file__).resolve().parents[2]


def func_src(rel, name, keep_doc=False):
    """Исходный текст функции/класса из файла проекта (без строки документации)."""
    src = (ROOT / rel).read_text(encoding="utf8")
    tree = ast.parse(src)
    for node in ast.walk(tree):
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)) and node.name == name:
            lines = src.splitlines()[node.lineno - 1 - len(node.decorator_list):node.end_lineno]
            text = "\n".join(lines)
            if not keep_doc and ast.get_docstring(node):
                text = re.sub(r'\n(\s+)"""(.|\n)*?"""\n', "\n", text, count=1)
            indent = len(lines[0]) - len(lines[0].lstrip())
            return "\n".join(ln[indent:] for ln in text.splitlines())
    raise KeyError(name)


def file_src(rel):
    return (ROOT / rel).read_text(encoding="utf8")


def yaml_doc(rel, kind, name):
    """Один YAML-документ из многодокументного манифеста."""
    for doc in file_src(rel).split("\n---\n"):
        if re.search(rf"kind: {kind}\b", doc) and re.search(rf"name: {name}\b", doc):
            return "\n".join(ln for ln in doc.strip().splitlines() if not ln.startswith("#"))
    raise KeyError(name)


