def appendices(start_bm=910):
    x = []
    items = [
        ("ПРИЛОЖЕНИЕ А", "Исходный код ключевых модулей микросервисов", [
            ("Листинг А.1 – Модуль правил микросервиса безопасности (wg_security/rules.py)",
             "services/security/wg_security/rules.py"),
            ("Листинг А.2 – Модуль шлюза доступа (wg_gateway/main.py)",
             "services/gateway/wg_gateway/main.py"),
            ("Листинг А.3 – Модуль токенов микросервиса аутентификации (wg_auth/tokens.py)",
             "services/auth/wg_auth/tokens.py")]),
        ("ПРИЛОЖЕНИЕ Б", "Манифесты Kubernetes", [
            ("Листинг Б.1 – Сетевые политики (deploy/k8s/10-network-policies.yaml)",
             "deploy/k8s/10-network-policies.yaml"),
            ("Листинг Б.2 – Манифест шлюза доступа (deploy/k8s/50-gateway.yaml)",
             "deploy/k8s/50-gateway.yaml")]),
        ("ПРИЛОЖЕНИЕ В", "Плейбук Ansible развертывания паттерна", [
            ("Листинг В.1 – Плейбук ansible/deploy.yml", "ansible/deploy.yml")]),
    ]
    for i, (title, sub, lst) in enumerate(items):
        x.append(page_break())
        x.append(heading1(title, start_bm + i, f"_Toc_app{i}", sub=sub))
        for cap, path in lst:
            x.append(listing(cap, file_src(path), size=16))
    return "".join(x), [(f"{t} {s}", f"_Toc_app{i}") for i, (t, s, _) in enumerate(items)]
